-- Rifts World Book 33: Northern Gun One - the 15 rail guns and non-energy weapons printed 204-212 that the catalog did not hold.
-- 15 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~282-northern-gun-1-weapons-rail.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-t9-dart-tranquilizer-pistol', 'NG-T9 Dart Tranquilizer Pistol', 'rifts', 'weapon', 3, 6500, 'Darts are 800 credits each. Very poor availability for the gun and darts outside Ishpeming', 'Tranquilizer dart: victim saves vs non-lethal poison (humans 16 or higher, D-Bees 12 or higher, with duration and penalties halved on nonhumans) or is knocked out for 1D4+1 melee rounds and groggy for 1D6+2 more; a successful save still leaves one melee round of grogginess. An adrenaline rush halves the duration', 0, '90 feet (27.4 m)', 'One dart', 'Single shot', NULL, NULL, NULL, 'A non-lethal dart pistol for subduing animals and people, favored by naturalists and explorers and by spies and thieves on snatch-and-grab jobs. The drug takes effect within five seconds. Grogginess halves combat bonuses and Spd, removes initiative and Perception bonuses, costs one melee attack and -15% on skills. No effect on supernatural beings, creatures of magic or Mega-Damage D-Bees, and the dart cannot penetrate even S.D.C. armor. -1 to strike even with W.P. Pistol or Revolver.', 'Rifts World Book 33: Northern Gun One p.204-205', NULL),
  ('ng-t12-tranquilizer-rifle', 'NG-T12 Tranquilizer Rifle', 'rifts', 'weapon', 6, 14500, 'Darts are 900 credits each. Very poor availability for the gun and darts outside Ishpeming', 'Tranquilizer dart, same as the NG-T9 pistol: save vs non-lethal poison or knocked out for 1D4+1 melee rounds, then groggy for 1D6+2 more', 0, '800 feet (244 m)', 'Two darts; hand-loaded, two melee actions to reload one dart, four to reload two', 'Single shot', NULL, NULL, NULL, 'A rifle firing the same tranquilizer dart as the NG-T9, with shorter range than a normal rifle. -1 to strike even with W.P. Rifle.', 'Rifts World Book 33: Northern Gun One p.205', NULL),
  ('ng-mc1-mega-crossbow', 'NG-MC1 Mega-Crossbow', 'rifts', 'weapon', 10, 15000, 'S.D.C. bolts 5-8 credits each; basic M.D.C. bolts 100 credits each; explosive bolts 400 (2D6 M.D.) or 800 (3D6 M.D.); flare/tracer and smoke bolts 120; tracker bug bolts 1,000 each and receiver handsets 2,000', 'M.D.C. bolts 1D6 M.D.; explosive heads 2D6 or 3D6 M.D.; plasma arrowheads 3D6 M.D. (double to beings vulnerable to fire/heat); S.D.C. bolts 2D6+2 S.D.C.; wooden stake 3D6+1 S.D.C. (double to vampires, range 600 feet/183 m); flares 3D6 S.D.C. (-1 to strike); tracker bug 2D6 S.D.C.; smoke bolts fill a 40 foot (12.2 m) area', 1, '1,200 feet (366 m); can fire to 1,500 feet (457 m) at -3 to strike beyond 1,200 feet', 'Up to six bolts clip onto the crossbow; quivers and cases typically hold 12, 24 or 32 bolts', 'Special: one melee attack to cock with a Supernatural, Robotic or Bionic P.S. or a human P.S. of 26 or higher; lesser P.S. needs the pulley system and 1D4 melee attacks. See W.P. Archery', NULL, NULL, 8, 'A high-powered Mega-Damage crossbow for silent kills, fighting vampires and firing specialty bolts (wooden, silver, flare, smoke, tracker bug, explosive). M.D. bolts weigh 8 ounces to 1.5 lbs (0.22-0.7 kg) each. +1 to strike on an aimed shot with a telescopic sight attached.', 'Rifts World Book 33: Northern Gun One p.205', NULL),
  ('ng-b10-bangstick', 'NG-B10 Bangstick', 'rifts', 'weapon', 4, 800, '800-1,200 credits, double for ornate walking sticks, canes or scepters; four M.D. shotgun shells come with each; shells 1,200 credits for a box of twenty or 100 each', 'Blunt: 2D6 S.D.C. +P.S. bonus, or 1D4 M.D. +P.S. M.D. punch damage with a P.S. capable of M.D. Shotgun shell on impact: 2D4 M.D. explosive, 4D6 S.D.C. buckshot, 5D6 S.D.C. solid slug, in addition to punch damage', 1, 'Close combat/impact', 'A single shotgun shell (any type, S.D.C. or M.D.), loaded by hand', NULL, NULL, NULL, NULL, 'A 2-3 foot (0.6-0.9 m) M.D.C. rod with a shotgun shell in a tube at the tip that fires when jabbed into a target; easy to conceal and still usable as a club after firing, and can parry M.D. melee weapons. Popular with City Rats, gangs, Juicers, Crazies and assassins.', 'Rifts World Book 33: Northern Gun One p.206', NULL),
  ('ng-b20-bangstick-hammer', 'NG-B20 Bangstick Hammer', 'rifts', 'weapon', 8, 1500, '1,500-2,000 credits for the 2-shot hammer, 2,500-3,000 for the 3-shot; double if ornate or with a single-shot apparatus in the handle base; eight M.D. shotgun shells come with each; shells 1,500 credits for a box of twenty', 'Blunt: 2D6 S.D.C. +P.S. bonus, or 1D6 M.D. +P.S. M.D. punch damage with a P.S. capable of M.D. Two-round head: 4D4 M.D. explosive, 1D4x10 S.D.C. buckshot, 1D6x10 S.D.C. slug. Three-round head: 4D6 M.D. explosive, 1D6x10 S.D.C. buckshot, 2D4x10 S.D.C. slug', 1, 'Close combat/impact', '2-3 shotgun shells (any type) in the hammer head, all fired together on impact; loaded by hand', NULL, NULL, NULL, NULL, 'A war hammer with a 2-4 foot handle, usable from horseback, hovercycles and flying power armor, whose M.D.C. head holds two or three shotgun rounds that go off on impact. Some carry a spike or claw for climbing, prying or hooking.', 'Rifts World Book 33: Northern Gun One p.206', NULL),
  ('ng-b30-bangstick-staff', 'NG-B30 Bangstick Staff', 'rifts', 'weapon', 6.5, 1500, '1,500-3,000 credits, double for ornate staves; four M.D. shotgun shells come with each; shells 1,200 credits for a box of twenty or 100 each', 'Blunt: 2D6 S.D.C. +P.S. bonus, or 1D6 M.D. +P.S. M.D. punch damage with a P.S. capable of M.D. Shell on impact: 2D4 M.D. explosive, 4D6 S.D.C. buckshot, 5D6 S.D.C. solid slug', 1, 'Close combat/impact', 'Two total, a single shell (any type) at each end; loaded by hand, two melee actions per shell', NULL, NULL, NULL, NULL, 'A 5-8 foot (1.5-2.4 m) Bangstick with a firing apparatus in both ends: jab with one end, then twirl or back-thrust to fire the other.', 'Rifts World Book 33: Northern Gun One p.206-207', NULL),
  ('ng-b40-big-bangstick', 'NG-B40 Big Bangstick BigBore Anti-Vampire Weapon', 'rifts', 'weapon', 11, 6000, '6,000-8,000 credits; silver-coating the rod 10,000 extra; BigBore shells 120 credits each or 16,000 a gross; 2-5 credits for wooden, solid or scattershot S.D.C. rounds; 100-200 for silver-coated solid shot; 400-600 for solid silver slug or scattershot', 'BigBore shell 2D4 M.D. each (knockdown per Rifts Black Market). Silver: solid 5D6 S.D.C., scattershot 2D6 S.D.C. to a two foot radius, double to vampires and werebeasts. Wood: solid 2D6+2 S.D.C., scattershot 1D4 S.D.C. to a three foot (0.9 m) radius, double to vampires. Silver handle blade 1D6 S.D.C.; silver-coated rod as a bludgeon 2D4 S.D.C.; both double to beings vulnerable to silver', 1, 'Melee, or 20 feet (6 m) firing the shotgun manually', 'Six shells, shotgun or BigBore', 'Each bang strike or shot counts as one melee attack', NULL, NULL, NULL, 'A thick 3-4 foot (0.9-1.2 m) rod with a concealed six-inch silver-coated knife blade in the handle and a double-barrel cylinder holding six Black Market BigBore shells (or wood, silver or S.D.C. shells) that fire when jabbed into a target. -2 to strike as a ranged weapon. The page gives the silver scattershot radius as two foot (1.2 m).', 'Rifts World Book 33: Northern Gun One p.207-208', NULL),
  ('ng-b50-thunderer-bigbore-combat-hammer', 'NG-B50 "Thunderer" BigBore Combat Hammer', 'rifts', 'weapon', 14, 17000, 'Includes silver-plating; BigBore shells 120 credits each or 16,000 a gross (144)', 'Blunt: 2D6 S.D.C. +P.S. bonus (double to vampires), or 1D6 M.D. +P.S. M.D. punch damage with a P.S. capable of M.D. BigBore shell 2D4 M.D. each (knockdown per Rifts Black Market). Silver: solid 5D6 S.D.C., scattershot 2D6 S.D.C. to a two foot (0.6 m) radius; wood: solid 2D6+2 S.D.C., scattershot 1D4 S.D.C. to a three foot (0.9 m) radius; all double to vampires and werebeasts', 1, 'Melee combat only', '8 total, four shells per side of the head; reloaded by hand, two melee actions per shell', '1D4 shells go off with each hit (or percentile: 01-25 one, 26-50 two, 51-75 three, 76-00 all four)', NULL, NULL, NULL, 'A massive two-handed war hammer whose two silver-coated faces each carry a central spike and four BigBore shell housings that fire at point-blank range on a killing blow. No ranged option; S.D.C., wood or silver shells may be substituted.', 'Rifts World Book 33: Northern Gun One p.208', NULL),
  ('ng-r50-mini-rail-gun', 'NG-R50 Mini-Rail Gun', 'rifts', 'weapon', 25, 30000, 'Two credits per round; standard E-Clip 6,000, long E-Clip 11,000 (recharge 1,500 and 2,000); power pack 30,000', '4D6 M.D.', 1, '1,500 feet (457.2 m)', '14 rounds from a short clip powered by a standard E-Clip, or 24 from a banana clip powered by a long E-Clip; a portable power pack (20 lbs/9 kg) powers 192 rounds', 'Each shot counts as one melee action', NULL, NULL, NULL, 'A light, compact rail gun firing large-caliber single shells rather than bursts; its technology led to the NG-505. A P.S. under 20 is -3 to strike.', 'Rifts World Book 33: Northern Gun One p.209', NULL),
  ('ng-303-infantry-mini-rail-gun', 'NG-303 Infantry Mini-Rail Gun', 'rifts', 'weapon', 27, 68000, 'Standard drum magazine 1,000 credits extra; backpack drum 2,800', '1D4 M.D. single round; a 10-round burst 4D6 M.D.', 1, '2,000 feet (610 m)', 'Ammo drum holds 200 rounds (20 bursts); a long E-Clip powers 40 rounds, as printed. Backpack drum for bionic or better P.S. holds 600 rounds (60 bursts)', 'Each ten round burst counts as one melee attack', NULL, NULL, NULL, 'A rail gun light enough for infantry, drawing on Triax and Bandito Arms designs; it burns through ammo fast. Weight includes a full drum. A P.S. under 21 is -2 to strike.', 'Rifts World Book 33: Northern Gun One p.210', NULL),
  ('ng-404-heavy-rail-gun', 'NG-404 Heavy Rail Gun', 'rifts', 'weapon', 460, 120000, '600-round ammo canisters 2,000 credits each; 2,400-round drum 8,000', '1D6 M.D. single round, or a 20-round burst 1D6x10 M.D.', 1, '5,000 feet (1,524 m)', '600 rounds (30 bursts) in a disintegrating link belt; two melee rounds for a two-man team to reload. A portable generator powers 1,200 bursts, or link to a vehicle''s nuclear supply. A 2,400-round drum (120 bursts, 35 M.D.C.) fits some of the largest vehicles', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'A three-barrel rotary rail gun firing larger-than-average rounds in controlled bursts; mounted on tanks, APCs and robots and on Ishpeming''s gun emplacements and anti-aircraft sites. A Robotic/Supernatural P.S. under 30 is -10 to strike.', 'Rifts World Book 33: Northern Gun One p.210', NULL),
  ('ng-505-heavy-rail-cannon', 'NG-505 Heavy Rail Cannon', 'rifts', 'weapon', 612, 175000, 'Gun alone; ammo drum (30 M.D.C.) 2,000 credits; 1,200 credits per shell; servo-rig turret mount 15,000', '1D6x10+3 M.D. to a three foot (0.9 m) radius', 1, '4,000 feet (1,219 m)', 'Built-in feeding drum holds 30 rounds; full-size 90-round drums also available', 'Each shot counts as one melee attack', NULL, NULL, NULL, 'A rail cannon firing a single large aerodynamic shell, for tanks, combat vehicles, light naval use and large robots such as the Hunter Mobile Gun and Gunbot. Also a rifle version needing Robotic P.S. 35 or Supernatural P.S. 25 (with one 90-round drum), and a towed field gun on a 65 M.D.C. carriage that takes about four melee rounds to anchor (-4 to strike unanchored).', 'Rifts World Book 33: Northern Gun One p.211', NULL),
  ('ng-1001-robot-rail-rifle', 'NG-1001 Robot Rail Rifle', 'rifts', 'weapon', 350, 95000, 'Ammo drum 4,000 credits with explosive rounds (exclusive to this weapon) or 2,000 with conventional rounds; energy ports in forearm or shoulder 30,000, back 25,000', '20-round burst: 1D6x10 M.D. explosive rounds or 4D6 M.D. conventional rail gun rounds', 1, '4,000 feet (1,219 m)', '920 rounds or 46 bursts per ammo drum (drum weighs 330 lbs/148.5 kg)', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'An oversized assault rifle famous from the Robodome games, for giant robots, power armor, giant D-Bees, demons and Golems; its independent power supply needs no hookup, and the drum belt-feeds from the user''s back.', 'Rifts World Book 33: Northern Gun One p.211', NULL),
  ('ng-r1002-robot-rail-gun-assault-rifle', 'NG-R1002 Robot Rail Gun/Assault Rifle', 'rifts', 'weapon', 265, 100000, 'Gun and power pack (may tie into the robot''s power supply); ammo canisters 8,000, 14,000 and 18,000 credits by size; fair availability at NG outlets, poor elsewhere', '40-round burst 1D4x10 M.D.; one round 1D4 M.D. The NG Super variant fires 60-round bursts for 1D6x10 M.D.', 1, '4,000 feet (1,219 m)', '2,400-round drum (60 bursts, 175 lbs/79 kg), 4,800-round drum (120 bursts, 350 lbs/157.5 kg) or 6,000-round drum (150 bursts, 500 lbs/225 kg)', 'Each single shot or burst counts as one melee attack', NULL, NULL, NULL, 'The NG-202 enlarged as a handheld weapon for giant combat robots, with the same range and a bigger drum. Power pack weighs 100 lbs (45 kg).', 'Rifts World Book 33: Northern Gun One p.212', NULL),
  ('ng-101-arg-automated-rail-gun', 'NG-101-ARG Automated Rail Gun', 'rifts', 'weapon', 285, 225000, '225,000 credits Solid Oxide, 185,000 electric battery; ammo drum (1,200 rounds) 5,000; ammo-block (50 M.D.C., 4,800 rounds) 18,000', '6D6 M.D. per 30 round burst', 1, '4,000 feet (1,219 m)', '1,200-round drum (40 bursts) with full mobility, or tethered within six feet (1.8 m) of a 4,800-round ammo-block (160 bursts)', 'Three attacks per melee round', NULL, NULL, 100, 'The Argonaut: an NG-101 rail gun on six robot legs with a computer brain that relocates, retreats and pursues, shooting anything in its field of vision; for wilderness borders, tunnels and corridors, not checkpoints. Sensors reach one mile (1.6 km), Read Sensory Equipment 74%, +3 to strike on a burst. Runs 20 mph (32 km) over rugged terrain and 50 degree inclines. M.D.C.: control pad 6 (-9 to strike), legs 15 each (-4 to strike), rail gun main body 100.', 'Rifts World Book 33: Northern Gun One p.212', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 15 gear rows are in' AS assertion, count(*) AS got, 15 AS want
  FROM gear WHERE slug IN ('ng-t9-dart-tranquilizer-pistol', 'ng-t12-tranquilizer-rifle', 'ng-mc1-mega-crossbow', 'ng-b10-bangstick', 'ng-b20-bangstick-hammer', 'ng-b30-bangstick-staff', 'ng-b40-big-bangstick', 'ng-b50-thunderer-bigbore-combat-hammer', 'ng-r50-mini-rail-gun', 'ng-303-infantry-mini-rail-gun', 'ng-404-heavy-rail-gun', 'ng-505-heavy-rail-cannon', 'ng-1001-robot-rail-rifle', 'ng-r1002-robot-rail-gun-assault-rifle', 'ng-101-arg-automated-rail-gun') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~282-northern-gun-1-weapons-rail.sql');
